import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const compareIds = (a, b) => a < b ? -1 : a > b ? 1 : 0;

// A min-heap lets newly available IDs compete with every ID already queued.
class IdHeap {
  items = [];

  push(id) {
    const items = this.items;
    let index = items.length;
    items.push(id);
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (items[parent] <= id) break;
      items[index] = items[parent];
      index = parent;
    }
    items[index] = id;
  }

  pop() {
    const items = this.items;
    const first = items[0];
    const last = items.pop();
    if (items.length > 0) {
      let index = 0;
      while (index * 2 + 1 < items.length) {
        let child = index * 2 + 1;
        if (child + 1 < items.length && items[child + 1] < items[child]) child++;
        if (last <= items[child]) break;
        items[index] = items[child];
        index = child;
      }
      items[index] = last;
    }
    return first;
  }
}

export function planJobs(spec) {
  if (!Array.isArray(spec)) throw new Error('Expected an array of jobs');
  const jobs = new Map();
  for (const job of spec) {
    if (job === null || typeof job !== 'object' || Array.isArray(job) ||
        typeof job.id !== 'string' || job.id.length === 0 ||
        !Array.isArray(job.deps) ||
        !['pending', 'succeeded', 'failed'].includes(job.state)) {
      throw new Error('Invalid job fields');
    }
    if (jobs.has(job.id)) throw new Error(`Duplicate job ID: ${job.id}`);
    const deps = new Set();
    for (const dep of job.deps) {
      if (typeof dep !== 'string' || dep.length === 0 || deps.has(dep)) {
        throw new Error(`Invalid or duplicate dependency for: ${job.id}`);
      }
      deps.add(dep);
    }
    jobs.set(job.id, {
      id: job.id, state: job.state, deps, children: [],
      indegree: deps.size, causes: new Set(),
    });
  }

  const available = new IdHeap();
  for (const job of jobs.values()) {
    for (const dep of job.deps) {
      if (!jobs.has(dep)) throw new Error(`Missing dependency: ${dep}`);
      jobs.get(dep).children.push(job);
    }
    if (job.indegree === 0) available.push(job.id);
  }

  const order = [], ready = [], blocked = [];
  let processed = 0;
  while (available.items.length > 0) {
    const job = jobs.get(available.pop());
    processed++;
    if (job.state === 'pending') {
      if (job.causes.size > 0) {
        blocked.push({ id: job.id, causes: [...job.causes].sort(compareIds) });
      } else {
        order.push(job.id);
        if ([...job.deps].every(dep => jobs.get(dep).state === 'succeeded')) {
          ready.push(job.id);
        }
      }
    }
    for (const child of job.children) {
      for (const cause of job.causes) child.causes.add(cause);
      if (job.state === 'failed') child.causes.add(job.id);
      if (--child.indegree === 0) available.push(child.id);
    }
  }
  if (processed !== jobs.size) throw new Error('Dependency cycle');
  ready.sort(compareIds);
  blocked.sort((a, b) => compareIds(a.id, b.id));
  return { order, ready, blocked };
}

if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node job-plan.js SPECFILE');
    const spec = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    const plan = planJobs(spec);
    process.stdout.write(`${JSON.stringify(plan)}\n`);
  } catch (error) {
    process.stderr.write(`${error.message}\n`);
    process.exitCode = 2;
  }
}
